def lookup(self, key, *, touch=True):
    if key not in self.data or self._expire_if_needed(key):
        self.stats.keyspace_misses += 1
        return None
    self.stats.keyspace_hits += 1
    if touch:
        self.data.move_to_end(key)
        self._atime[key] = next(self._access_clock)
    return self.data[key]

# real: minidis/keyspace.py
def lookup_typed(self, key, typ, *, create=None):
    value = self.lookup(key)
    if value is None:
        if create is None:
            return None
        value = create()
        self.store(key, value, keep_ttl=False)
        return value
    if not isinstance(value, typ):
        raise WRONGTYPE
    return value

