LOADERS = {1: _load_v1, 2: _load_v2}

def load(data, ks):
    if not data.startswith(b"MINIDIS"):
        raise CorruptSnapshot("bad magic")
    version = data[7]
    loader = LOADERS.get(version)
    if loader is None:
        raise CorruptSnapshot(f"unsupported snapshot version {version}")
    return loader(data, ks)

