# illustrative (not in repo): backlog in _propagate
class Backlog:
    def __init__(self, size):
        self.buf = bytearray(); self.size = size; self.start = 0   # offset of buf[0]
    def append(self, data, end_offset):
        self.buf += data
        if len(self.buf) > self.size:
            drop = len(self.buf) - self.size
            del self.buf[:drop]; self.start += drop
    def since(self, offset):            # None -> needs full resync
        if offset < self.start or offset > self.start + len(self.buf):
            return None
        return bytes(self.buf[offset - self.start:])
